const normalize=s=>String(s||'').normalize('NFC').toLowerCase().replace(/[\s·ㆍ\-()]/g,'');
const CHO='ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ';
export const initials=s=>[...s].map(c=>{const n=c.charCodeAt(0)-44032;return n>=0&&n<11172?CHO[Math.floor(n/588)]:c;}).join('');
export function searchPlaces(places,query,limit=6){const q=normalize(query);if(!q)return[];const tokens=q.split(/[,/]+/).filter(Boolean);return places.map(p=>{const names=[p.name,p.originalName,p.short,...p.aliases||[]].filter(Boolean).map(normalize),fields=[...names,normalize(p.category),normalize(p.area),normalize(p.address),normalize(p.blurb)];let score=0;for(const token of tokens){const scores=names.map(n=>n===token?100:n.startsWith(token)?80:n.includes(token)?60:initials(n)===token?75:initials(n).startsWith(token)?50:initials(n).includes(token)?40:0);const part=Math.max(...scores,...fields.map(n=>n.includes(token)?20:0));if(!part)return null;score+=part;}return{p,score};}).filter(Boolean).sort((a,b)=>b.score-a.score||Number(a.p.remote)-Number(b.p.remote)||a.p.name.localeCompare(b.p.name,'ko')).slice(0,limit).map(x=>x.p);}
export function setupPlaceSearch(places,onSelect,onFocus){const root=document.querySelector('#place-search'),input=root.querySelector('input'),list=root.querySelector('[role=listbox]'),clear=root.querySelector('button');let results=[],active=-1,composing=false;
 const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;};
 const highlight=()=>{[...list.querySelectorAll('[role=option]')].forEach((el,i)=>el.setAttribute('aria-selected',String(i===active)));if(active>=0)input.setAttribute('aria-activedescendant','place-result-'+active);else input.removeAttribute('aria-activedescendant');};
 const choose=i=>{const p=results[i];if(!p)return;input.value=p.name;close();input.blur();onSelect(p);};
 const render=()=>{results=searchPlaces(places,input.value);active=-1;input.removeAttribute('aria-activedescendant');list.replaceChildren();if(!input.value.trim()){close();return;}list.hidden=false;input.setAttribute('aria-expanded','true');if(!results.length){const li=document.createElement('li');li.className='search-empty';li.textContent='찾는 장소가 없어요. 이름을 짧게 써 볼까요?';list.append(li);return;}for(const[pidx,p]of results.entries()){const li=document.createElement('li');li.id='place-result-'+pidx;li.setAttribute('role','option');li.setAttribute('aria-selected','false');const name=document.createElement('strong'),meta=document.createElement('small');name.textContent=p.name;meta.textContent=p.area+' · '+p.category+(p.remote?' · 이야기로 보기':' · 찾아가기');li.append(name,meta);li.addEventListener('pointerdown',e=>e.preventDefault());li.addEventListener('click',()=>choose(pidx));list.append(li);} };
 input.addEventListener('input',render);input.addEventListener('focus',()=>{onFocus?.();render();});input.addEventListener('compositionstart',()=>composing=true);input.addEventListener('compositionend',()=>{composing=false;render();});
 input.addEventListener('keydown',e=>{if(e.isComposing||composing)return;if(e.key==='Escape'){close();input.blur();onFocus?.(false);}else if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(list.hidden)render();active=results.length?(active+(e.key==='ArrowDown'?1:-1)+results.length)%results.length:-1;highlight();}else if(e.key==='Enter'){e.preventDefault();choose(active<0?0:active);}});
 root.addEventListener('submit',e=>{e.preventDefault();if(!composing)choose(active<0?0:active);});clear.onclick=()=>{input.value='';close();input.focus();};document.addEventListener('pointerdown',e=>{if(!root.contains(e.target))close();});input.addEventListener('blur',()=>setTimeout(()=>{if(!root.contains(document.activeElement))close();},100));return{close};
}
